    def __init__(self, N=3):
        self.board = [[' ' for _ in range(N)] for _ in range(N)]
        self.current_player = 'X'

    def make_move(self, row, col):
        if 0 <= row < 3 and 0 <= col < 3 and self.board[row][col] == ' ':
            self.board[row][col] = self.current_player
            self.current_player = 'O' if self.current_player == 'X' else 'X'
            return True
        return False

    def check_winner(self):
        N = len(self.board)
        for row in range(N):
            if all(self.board[row][col] == self.current_player for col in range(N)):
                return self.current_player
        for col in range(N):
            if all(self.board[row][col] == self.current_player for row in range(N)):
                return self.current_player
        if all(self.board[i][i] == self.current_player for i in range(N)) or \
           all(self.board[i][N-1-i] == self.current_player for i in range(N)):
            return self.current_player
        return None

    def is_board_full(self):
        return all(self.board[row][col] != ' ' for row in range(3) for col in range(3))
